  $c = Get-Content $_.FullName -Raw -Encoding UTF8
  if($c -match '🪶'){ "🪶 in " + $_.Name }
  if($c -match '🔮'){ "🔮 in " + $_.Name }
}
"--- 00 文件里甘雨抄录段 ---"
$c = Get-Content "$d\00-lexicon-scout.md" -Raw -Encoding UTF8
$i = $c.IndexOf('图1 · 头部')
if($i -ge 0){ $c.Substring($i, [Math]::Min(1500, $c.Length-$i)) }"}

